const questions=[];
function add(subtheme,difficulty,source,block){for(const line of block.trim().split('\n')){const [question,answer,...rest]=line.split('¦');const explanation=rest.pop(),raw=[answer,...rest],shift=questions.length%4;questions.push({id:`v3-tech-${String(questions.length+1).padStart(3,'0')}`,category:'tech',subtheme,difficulty,type:'qcm',question,options:[...raw.slice(shift),...raw.slice(0,shift)],correct:(4-shift)%4,explanation,source});}}
